const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds, shadows, and water for Landsat 7 C2 L2
function maskL7sr(image) {
  // Bits 3, 4, and 5 are cloud shadow, snow, and cloud. Bit 7 is water.
  const cloudShadowBitMask = (1 << 3);
  const snowBitMask = (1 << 4);
  const cloudBitMask = (1 << 5);
  const waterBitMask = (1 << 7);
  const qa = image.select('QA_PIXEL');
  // All flags should be set to zero, indicating clear conditions.
  let mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(snowBitMask).eq(0))
                 .and(qa.bitwiseAnd(cloudBitMask).eq(0))
                 .and(qa.bitwiseAnd(waterBitMask).eq(0));
  return image.updateMask(mask);
}

// Function to calculate NBR
function calculateNBR(image) {
  // Landsat 7 C2 L2: NIR = SR_B4, SWIR2 = SR_B7
  return image.normalizedDifference(['SR_B4', 'SR_B7']).rename('NBR');
}

// Function to calculate burn area based on an NBR threshold
function getBurnArea(image, geometry, scale, threshold) {
  const burnedPixels = image.lt(threshold); // Pixels with NBR less than threshold
  const areaImage = burnedPixels.multiply(ee.Image.pixelArea());
  const area = areaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  });
  return ee.Number(area.get('NBR'));
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-110.517217, 45.506013]);
  const aoi = point.buffer(3000);
  const dateRange1 = ee.DateRange('2012-08-10', '2012-08-20');
  const dateRange2 = ee.DateRange('2012-09-10', '2012-09-20');
  const BURN_THRESHOLD = 0.1; // NBR threshold for identifying burned areas
  const SCALE = 30; // Landsat scale

  // 2. Data Acquisition
  let col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
                .filterBounds(aoi);

  const col1 = col.filterDate(dateRange1);
  const col2 = col.filterDate(dateRange2);

  const col1Size = col1.size().getInfo();
  const col2Size = col2.size().getInfo();

  if (col1Size === 0 || col2Size === 0) {
    console.log(`Image count check failed. Period 1: ${col1Size}, Period 2: ${col2Size}.`);
    console.log("C1");
    return;
  }
  console.log(`Initial image count -> Aug: ${col1Size}, Sep: ${col2Size}`);

  // 3. Processing
  const image1 = col1.map(maskL7sr).map(calculateNBR).median().clip(aoi);
  const image2 = col2.map(maskL7sr).map(calculateNBR).median().clip(aoi);

  // Check for valid pixels after masking
  const pixelCount1 = image1.reduceRegion({ reducer: ee.Reducer.count(), geometry: aoi, scale: SCALE, maxPixels: 1e9 }).get('NBR').getInfo();
  const pixelCount2 = image2.reduceRegion({ reducer: ee.Reducer.count(), geometry: aoi, scale: SCALE, maxPixels: 1e9 }).get('NBR').getInfo();

  if (pixelCount1 === 0 || pixelCount2 === 0) {
    console.log(`Valid pixel check failed. Aug pixels: ${pixelCount1}, Sep pixels: ${pixelCount2}.`);
    console.log("C2");
    return;
  }
  console.log(`Valid pixels after masking -> Aug: ${pixelCount1}, Sep: ${pixelCount2}`);

  // 4. Calculation
  const burnArea1 = getBurnArea(image1, aoi, SCALE, BURN_THRESHOLD);
  const burnArea2 = getBurnArea(image2, aoi, SCALE, BURN_THRESHOLD);

  const area1_sq_km = ee.Number(burnArea1).divide(1e6).getInfo();
  const area2_sq_km = ee.Number(burnArea2).divide(1e6).getInfo();

  if (area1_sq_km === null || area2_sq_km === null) {
      console.log(`Calculation failed. Aug Area: ${area1_sq_km}, Sep Area: ${area2_sq_km}.`);
      console.log("C3");
      return;
  }

  // 5. Validation & Final Answer
  console.log(`Burn Area (NBR < ${BURN_THRESHOLD}) mid-Aug 2012: ${area1_sq_km.toFixed(2)} sq km`);
  console.log(`Burn Area (NBR < ${BURN_THRESHOLD}) mid-Sep 2012: ${area2_sq_km.toFixed(2)} sq km`);

  if (area2_sq_km > area1_sq_km) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
